export const VERSION='0.4.0';
export const NEEDS={energy:'Énergie',social:'Lien social',fun:'Plaisir',expression:'Expression',comfort:'Confort'};
export const PERSONALITY={creative:'Créativité',outgoing:'Extraversion',kind:'Empathie',discipline:'Discipline',stable:'Stabilité',ambition:'Ambition'};
export const SKILLS={guitar:'Guitare',bass:'Basse',drums:'Batterie',voice:'Chant',keys:'Clavier',sax:'Saxophone',trumpet:'Trompette',percussion:'Percussions',writing:'Composition'};
export const GENRES=['Indie','Punk','Folk','Métal','Jazz','Électro','Ska','Pop'];
export const TRAITS={night:'Oiseau de nuit',shy:'Timide',hot:'Impulsif',perfectionist:'Perfectionniste',friendly:'Chaleureux',loner:'Solitaire',virtuoso:'Oreille musicale',lazy:'Relax',sensitive:'Sensible'};
export const EMOTIONS={joy:{label:'Joie',levels:['Contentement','Joie','Euphorie'],color:'#c4a44d',tone:'lumineuse',icon:'☀'},sadness:{label:'Tristesse',levels:['Mélancolie','Tristesse','Chagrin'],color:'#7794bb',tone:'mélancolique',icon:'☂'},anger:{label:'Colère',levels:['Agacement','Colère','Rage'],color:'#cb785c',tone:'rageuse',icon:'ϟ'},fear:{label:'Peur',levels:['Inquiétude','Anxiété','Panique'],color:'#a790b3',tone:'tendue',icon:'◈'},affection:{label:'Affection',levels:['Sympathie','Tendresse','Amour'],color:'#c88fa0',tone:'intime',icon:'♡'},excitement:{label:'Enthousiasme',levels:['Curiosité','Enthousiasme','Exaltation'],color:'#83a474',tone:'énergique',icon:'✦'}};
