export const ACTIONS={sleep:{label:'Se reposer',icon:'☾',duration:110,description:'Récupère de l’énergie et du confort à la maison.'},social:{label:'Socialiser',icon:'♡',duration:50,description:'Retrouve des voisins au café, au parc ou au disquaire ; les échanges font évoluer les liens.'},practice:{label:'Pratiquer',icon:'♫',duration:65,description:'Travaille son instrument seul dans un garage et améliore sa compétence.'},jam:{label:'Jammer ensemble',icon:'♬',duration:85,description:'Propose ou rejoint une session. La musique commence à deux, au même garage. Sans partenaire après 90 minutes sur place, revient à la pratique solo.'},write:{label:'Composer',icon:'✎',duration:75,description:'Chaque séance avance un projet persistant : idée, ébauche puis chanson. Plusieurs séances sont nécessaires ; le projet et ses causes restent visibles sur la fiche.'},relax:{label:'Décrocher',icon:'☀',duration:45,description:'Au parc, restaure plaisir et confort et apaise les émotions négatives.'},form:{label:'Former un groupe',icon:'✚',duration:20,description:'Retrouve un partenaire avec une affinité réciproque suffisante et un vécu musical commun ; fonde ou rejoint un groupe.'}};
export const PLACES=[{id:'g1',name:'Garage des Érables',kind:'garage',x:100,y:94,w:220,h:132,door:{x:210,y:253},color:'#bdcced'}, {id:'cafe',name:'Chez Jo · café des voisins',kind:'cafe',x:420,y:100,w:210,h:126,door:{x:525,y:253},color:'#edc699'}, {id:'g2',name:'Garage du Canal',kind:'garage',x:755,y:94,w:225,h:132,door:{x:867,y:253},color:'#bdcfb4'}, {id:'home1',name:'Maisons · rue des Érables',kind:'home',x:90,y:446,w:205,h:125,door:{x:192,y:420},color:'#d5cbbd'}, {id:'park',name:'Parc des Amplis',kind:'park',x:400,y:440,w:250,h:135,door:{x:525,y:420},color:'#a9c69d'}, {id:'shop',name:'Le disquaire',kind:'disquaire',x:790,y:444,w:190,h:125,door:{x:885,y:420},color:'#d7bdd5'}];
export const DEFAULTS={drain:1,music:1,social:1,conflict:1,learning:1,randomness:.3,relations:1,emotionDecay:1,romance:1,compositionPace:1};

export const clamp=(x,a=0,b=100)=>Math.max(a,Math.min(b,x));
export const round=x=>Math.round(x)||0;
export function rand(s){s.rng=(Math.imul(s.rng,1664525)+1013904223)>>>0;return s.rng/4294967296;}
const pick=(s,a)=>a[Math.floor(rand(s)*a.length)];
const range=(s,a,b)=>a+rand(s)*(b-a);
const emptyEmotions=()=>Object.fromEntries(Object.keys(EMOTIONS).map(k=>[k,0]));
const priorities=()=>Object.fromEntries(Object.keys(ACTIONS).map(k=>[k,2]));
const musical=['practice','jam','write'];
const sociable=['social','relax'];
const names=['Alex','Sam','Jo','Charlie','Lou','Max','Camille','Noa','Mika','Robin','Kim','Fred','Jules','Morgan','Éli','Sacha','Raphaël','Ari','Jess','Rémi','Léa','Val','Pat','Mel'];
const colors=['#d67753','#7192b3','#9a79ad','#c0a646','#629c84','#c78196','#75894d','#5b939d'];
export const relKey=(a,b)=>`${a}>${b}`;
// Attraction is directed and stable at first encounter. Reading it never advances the RNG.
function attraction(a,b){let hash=2166136261;for(const c of `${a.id}/${b.id}/${a.personality.creative}/${b.personality.kind}`)hash=Math.imul(hash^c.charCodeAt(0),16777619)>>>0;return 10+hash%71;}
export function relationship(s,a,b){const key=relKey(a.id,b.id);if(!s.rels[key])s.rels[key]={affinity:0,trust:10,tension:0,collaboration:0,attraction:attraction(a,b),love:0,meetings:0,last:0,lastAdvance:-1440,musicSessions:0};return s.rels[key];}
export function chemistry(a,b){let similarity=1-(Math.abs(a.personality.creative-b.personality.creative)+Math.abs(a.personality.discipline-b.personality.discipline))/200;return clamp(25+similarity*30+(a.genre===b.genre?25:0)+(a.instrument!==b.instrument?10:-6)+(a.personality.kind+b.personality.kind)/20);}
export function dominantEmotion(p){const [key,value]=Object.entries(p.emotions).sort((a,b)=>b[1]-a[1])[0];return {key,value,level:value<34?1:value<67?2:3,label:value<10?'Paisible':EMOTIONS[key].levels[value<34?0:value<67?1:2],active:value>=10};}
export function mood(p){const e=p.emotions;return clamp(Object.values(p.needs).reduce((a,b)=>a+b,0)/Object.keys(NEEDS).length+p.memories.reduce((a,m)=>a+m.effect,0)+(e.joy+e.affection+e.excitement-e.sadness-e.anger-e.fear)*.045);}
export function stamp(time){return `J${Math.floor(time/1440)+1} ${String(Math.floor(time%1440/60)).padStart(2,'0')}:${String(time%60).padStart(2,'0')}`;}
export function log(s,type,text,ids=[],details={}){const actor=s.people.find(p=>p.id===ids[0]);const linked=['decision','social','music','conflict','support','romance','jam','project'].includes(type);const activityId=details.activityId||(linked?actor?.action?.activityId:null);const e={id:++s.eventId,time:s.time,type,text,ids,...details,...(activityId?{activityId}:{})};s.events.unshift(e);s.events=s.events.slice(0,500);const activity=s.activities?.find(a=>a.id===activityId);if(activity){activity.ids=[...new Set([...activity.ids,...ids])];activity.events.push({...e});activity.events=activity.events.slice(-24);}return e;}
function beginActivity(s,p,a){const id=a.key==='jam'?a.sessionId:`a${s.nextActivityId++}`;a.activityId=id;let row=s.activities.find(x=>x.id===id);if(!row){row={id,key:a.key,time:s.time,end:null,place:a.dest,ids:[],status:a.route.length?'travel':'active',activeMinutes:0,events:[]};s.activities.unshift(row);}if(!row.ids.includes(p.id))row.ids.push(p.id);const live=s.activities.filter(x=>!x.end),past=s.activities.filter(x=>x.end&&s.time-x.end<1440*14).slice(0,Math.max(0,240-live.length));s.activities=[...live,...past].sort((a,b)=>b.time-a.time);return row;}
function closeActivity(s,p,status='completed'){const a=p.action,row=s.activities.find(x=>x.id===a?.activityId);if(!row)return;if(a.key==='jam'&&s.people.some(q=>q!==p&&q.action?.sessionId===a.sessionId))return;row.status=status;row.end=s.time;row.activeMinutes=Math.max(row.activeMinutes,a.elapsed);}
export function journalEntries(s,{raw=false,filter='all',selected=null}={}){const matches=e=>filter==='all'||filter==='selected'&&e.ids.includes(selected)||filter==='social'&&['social','conflict','support','romance'].includes(e.type)||filter==='music'&&['music','jam','project','song'].includes(e.type)||e.type===filter;if(raw)return s.events.filter(matches);const rows=s.activities.map(a=>({...a,type:a.key==='jam'?'jam':a.key==='write'?'project':'activity',session:true,text:`${ACTIONS[a.key].label} · ${a.ids.map(id=>s.people.find(p=>p.id===id)?.name||'Ancien voisin').join(', ')}`})).filter(a=>filter==='all'||filter==='selected'&&a.ids.includes(selected)||filter==='jam'&&a.key==='jam'||filter==='music'&&['jam','write','practice'].includes(a.key)||filter==='decision'||a.events.some(matches));return [...rows,...s.events.filter(e=>!e.activityId&&matches(e))].sort((a,b)=>b.time-a.time||String(b.id).localeCompare(String(a.id)));}
export function chemistryKnowledge(s,a,b){const sessions=Math.min(relationship(s,a,b).musicSessions||0,relationship(s,b,a).musicSessions||0);const value=chemistry(a,b);return {sessions,confidence:sessions===0?'Inconnue':sessions<3?'Impression incertaine':sessions<6?'Tendance observée':'Tendance confirmée',grade:sessions===0?'?':value>=80?'Très prometteuse':value>=65?'Prometteuse':value>=45?'Contrastée':'Difficile',known:sessions>0};}
const TITLE_PARTS={sadness:['Le silence','La dernière nuit','Une chaise vide','Les départs','Le dernier bus'],anger:['Le mur','Les amplis','Les étincelles','La tempête','Les mots de trop'],affection:['Nos accords','Une place','Les mains','Les retrouvailles','Le cœur'],fear:['Les ombres','Les murs','Un souffle','Les pas','Le vertige'],joy:['Les fenêtres','Le matin','Les érables','Les lumières','La rue'],excitement:['Le départ','Les néons','La route','Le volume','Le premier refrain']};
function projectTitle(s,emotion){const endings=['du quartier','à minuit','dans le garage','sous la pluie','du canal','sans détour','en suspens','au loin','de septembre','au bout de la rue','en mouvement','à contretemps'];const base=pick(s,TITLE_PARTS[emotion])+ ' '+pick(s,endings);let title=base,n=2;while(s.projects.some(x=>x.title===title)||s.songs.some(x=>x.title===title))title=base+' · '+n++;return title;}
function ensureProject(s,p){let project=s.projects.find(x=>x.id===p.draft.projectId&&x.status!=='finished');if(project)return project;const emotion=dominantEmotion(p).key;project={id:`c${s.nextProjectId++}`,author:p.id,title:projectTitle(s,emotion),genre:p.genre,created:s.time,updated:s.time,work:0,target:300+(100-p.personality.discipline)*.75,sessions:0,status:'idea',emotion,tone:EMOTIONS[emotion].tone,intensity:round(p.emotions[emotion]),sources:[],potential:round(clamp(p.skills.writing*.45+p.skills[p.instrument]*.25+p.emotions[emotion]/100*(6+p.personality.creative*.12)+(p.traits.includes('perfectionist')?8:0))),songId:null};s.projects.push(project);p.draft.projectId=project.id;const idea=s.activities.flatMap(a=>a.events).filter(e=>e.outcome==='idea'&&e.ids.includes(p.id)&&s.time-e.time<1440&&!s.projects.some(x=>x.id!==project.id&&x.author===p.id&&x.sources.some(c=>c.id===e.id))).sort((a,b)=>b.time-a.time)[0];if(idea){p.draft.sources.push({id:idea.id,time:idea.time,text:idea.text});p.draft.jamQuality=4;p.draft.jamSamples=1;project.sources=[...p.draft.sources];}return project;}
export function compositionProject(s,p){return s.projects.find(x=>x.id===p.draft.projectId&&x.status!=='finished')||null;}
function advanceProject(s,p){const project=ensureProject(s,p);project.work=Math.min(project.target,project.work+s.params.compositionPace*(.85+p.personality.discipline/300));project.updated=s.time;project.status=project.work/project.target<.25?'idea':project.work/project.target<1?'draft':'ready';p.songProgress=clamp(project.work/project.target*100);project.potential=round(clamp(p.skills.writing*.45+p.skills[p.instrument]*.25+project.intensity/100*(6+p.personality.creative*.12)+(p.traits.includes('perfectionist')?8:0)));if(p.draft.samples<=75){const result=Object.entries(p.draft.emotions).sort((a,b)=>b[1]-a[1])[0];project.emotion=result[0];project.intensity=round(result[1]/Math.max(1,p.draft.samples));project.tone=project.intensity<10?'posée':EMOTIONS[project.emotion].tone;project.sources=[...p.draft.sources];}}

function memory(s,p,text,effect){effect*=((p.traits.includes('sensitive')?1.5:1)*(1.3-p.personality.stable/200));p.memories.unshift({text,effect:Math.round(effect*10)/10,until:s.time+360});p.memories=p.memories.slice(0,6);}
export function feel(s,p,changes,source){for(const [key,amount] of Object.entries(changes)){const multiplier=amount>0?(p.traits.includes('sensitive')?1.3:1)*(1.15-p.personality.stable/300):1;p.emotions[key]=clamp(p.emotions[key]+amount*multiplier);if(amount>0&&source){p.emotionSources[key]=[{id:source.id,time:source.time,text:source.text},...(p.emotionSources[key]||[]).filter(x=>x.id!==source.id)].slice(0,3);}}}
function defaultDraft(){return {projectId:null,samples:0,emotions:emptyEmotions(),sources:[],authors:[],jamQuality:0,jamSamples:0};}
export function addPerson(s){if(s.people.length>=24)return null;let n=s.nextId++,personality=Object.fromEntries(Object.keys(PERSONALITY).map(k=>[k,round(range(s,20,85))]));let traits=[];for(let i=0;i<2;i++){let t=pick(s,Object.keys(TRAITS));if(!traits.includes(t))traits.push(t);}let instrument=pick(s,Object.keys(SKILLS).filter(k=>k!=='writing'));let start=pick(s,PLACES),door=start.door;
let p={id:`p${n}`,name:names[(n-1)%names.length]+(n>24?' '+n:''),color:colors[(n-1)%colors.length],age:round(range(s,19,47)),instrument,genre:pick(s,GENRES),personality,traits,skills:Object.fromEntries(Object.keys(SKILLS).map(k=>[k,round(range(s,k===instrument?30:5,k===instrument?65:25))])),needs:Object.fromEntries(Object.keys(NEEDS).map(k=>[k,round(range(s,50,90))])),x:door.x+range(s,-25,25),y:door.y,home:'home1',place:start.id,action:null,candidates:[],memories:[],history:[],songProgress:0,emotions:{...emptyEmotions(),joy:12,excitement:18},emotionSources:{},priorities:priorities(),draft:defaultDraft(),lastFormation:-1440,actionCounts:Object.fromEntries(Object.keys(ACTIONS).map(k=>[k,{started:0,completed:0,interrupted:0}])),countsSince:s.time,reputation:{score:0,skill:0,catalogue:0,recognition:0,collaboration:0}};
s.people.push(p);for(const b of s.people)if(b!==p){relationship(s,p,b);relationship(s,b,p);}refreshReputation(s,p);log(s,'system',`${p.name} s’installe dans le quartier.`,[p.id]);return p;}
export function createWorld(seed=2040,count=8){const s={version:VERSION,time:480,rng:seed>>>0,seed:seed>>>0,nextId:1,eventId:0,nextSongId:1,nextGroupId:1,nextJamId:1,nextActivityId:1,nextProjectId:1,activities:[],projects:[],people:[],rels:{},events:[],songs:[],groups:[],jams:[],params:{...DEFAULTS},scenario:'Équilibre',history:[],decisionMode:'utility'};for(let i=0;i<count;i++)addPerson(s);for(const p of s.people){refreshReputation(s,p);decide(s,p);}return s;}
export function groupsOf(s,p){return s.groups.filter(g=>g.members.includes(p.id));}
export function isMember(s,p){return groupsOf(s,p).length>0;}
export function refreshReputation(s,p){const songs=s.songs.filter(x=>x.authors.includes(p.id)),avg=songs.length?songs.reduce((a,x)=>a+x.quality,0)/songs.length:0;const known=s.people.filter(x=>x!==p).map(x=>relationship(s,x,p));const skill=p.skills[p.instrument]*.25,catalogue=avg*.3*(1-Math.exp(-songs.length/2)),recognition=Math.min(25,[...songs].sort((a,b)=>(b.resonance??b.quality)-(a.resonance??a.quality)).slice(0,8).reduce((a,x)=>a+(x.resonance??x.quality)/100,0)*3.125),collaboration=Math.min(20,known.reduce((a,r)=>a+r.collaboration/100,0)*5);p.reputation={score:round(clamp(skill+catalogue+recognition+collaboration)),skill:round(skill),catalogue:round(catalogue),recognition:round(recognition),collaboration:round(collaboration)};return p.reputation;}
export function formationEligible(s,a,b){if(a===b)return false;const ab=relationship(s,a,b),ba=relationship(s,b,a);return ab.affinity>=22&&ba.affinity>=22&&Math.min(ab.trust,ba.trust)>=18&&Math.max(ab.tension,ba.tension)<40&&(Math.min(ab.collaboration,ba.collaboration)>=10||Math.min(ab.affinity,ba.affinity)>=40);}
export function formationPlan(s,p){if(s.time-p.lastFormation<720)return null;const peers=s.people.filter(q=>q!==p&&formationEligible(s,p,q)).sort((a,b)=>(b.reputation.score+relationship(s,p,b).affinity)-(a.reputation.score+relationship(s,p,a).affinity));for(const q of peers){const shared=s.groups.some(g=>g.members.includes(p.id)&&g.members.includes(q.id));if(shared)continue;const group=groupsOf(s,q).find(g=>!g.members.includes(p.id)&&g.members.filter(id=>formationEligible(s,p,s.people.find(x=>x.id===id))).length>=Math.ceil(g.members.length/2));return {partner:q.id,groupId:group?.id||null};}return null;}
export function createGroup(s,ids,{name=null,manual=false}={}){const members=[...new Set(ids)].filter(id=>s.people.some(p=>p.id===id));if(members.length<2)return null;const existing=s.groups.find(g=>g.members.length===members.length&&members.every(id=>g.members.includes(id)));if(existing)return existing;const founders=members.slice(0,2),p=s.people.find(x=>x.id===founders[0]),q=s.people.find(x=>x.id===founders[1]);if(!manual&&!formationEligible(s,p,q))return null;const group={id:`g${s.nextGroupId++}`,name:name||pick(s,['Les Amplis du coin','Rue des Érables','Les Notes de travers','Minuit au garage','Les Voisins électriques','Le Dernier Accord'])+' '+(s.nextGroupId-1),members,founders,created:s.time,genre:p.genre,origin:manual?'laboratoire':'autonome'};s.groups.push(group);const ev=log(s,'group',`${manual?'Intervention : ':''}${members.map(id=>s.people.find(p=>p.id===id).name).join(', ')} forment « ${group.name} ».`,members,{groupId:group.id});for(const id of members){const p=s.people.find(x=>x.id===id);p.lastFormation=s.time;feel(s,p,{excitement:16,affection:7},ev);}return group;}
function critical(p){return p.needs.energy<15?'sleep':null;}
export function scores(s,p){const n=p.needs,t=p.personality,e=p.emotions,night=s.time%1440>=1320||s.time%1440<420;
const rows=[['sleep',(100-n.energy)*1.25+(night?25:0)+(p.traits.includes('night')&&night?-22:0),`Énergie ${round(n.energy)}/100${night?' · nuit':''}`,e.sadness*.12+e.fear*.08],['social',(100-n.social)*(.65+t.outgoing/100)*s.params.social+(p.traits.includes('friendly')?12:0)-(p.traits.includes('loner')?18:0)-(p.traits.includes('shy')?10:0),`Lien social ${round(n.social)} · extraversion ${t.outgoing}`,e.affection*.23+e.joy*.1-e.fear*.12-e.anger*.12],['practice',((100-n.expression)*.7+t.discipline*.25+t.ambition*.15)*s.params.music,`Expression ${round(n.expression)} · discipline ${t.discipline}`,e.excitement*.16+e.anger*.1],['jam',((100-n.expression)*.4+(100-n.social)*.4+t.outgoing*.25)*s.params.music,`Expression ${round(n.expression)} · lien social ${round(n.social)}`,e.excitement*.2+e.joy*.1-e.fear*.12],['write',((100-n.expression)*.6+t.creative*.38)*s.params.music,`Créativité ${t.creative} · expression ${round(n.expression)}`,Math.max(...Object.values(e))*.32*(.4+t.creative/100)],['relax',(100-n.fun)*.7+(100-n.comfort)*.65+(p.traits.includes('lazy')?15:0),`Plaisir ${round(n.fun)} · confort ${round(n.comfort)}`,e.fear*.3+e.anger*.17],['form',65+t.ambition*.15,`Un lien réciproque et une envie de jouer ensemble`,e.excitement*.08]];
const urgent=critical(p),plan=formationPlan(s,p);let list=rows.map(([key,base,why,emotion])=>{const priority=p.priorities[key],factor=({0:0,1:1.65,2:1,3:.55})[priority];let blocked=priority===0?'Interdit par priorité':key==='form'&&!plan?'Aucun nouveau partenaire admissible ou délai de 12 h':null;let score=blocked?0:Math.max(0,(base+emotion)*factor);if(urgent===key){blocked=null;score=1000;why+=' · énergie critique';}return {key,base:round(base),emotion:round(emotion),priority,factor,bandBoost:1,invite:0,score,why,blocked};});
// Essential self-care is always available. No priority can suppress a critical need.
if(!list.some(c=>!c.blocked&&c.score>0)){let rest=list.find(c=>c.key==='relax');rest.blocked=null;rest.score=1;rest.why='Aucune autre activité autorisée : repos libre';}
let total=list.reduce((n,c)=>n+c.score*c.score,0);return list.map(c=>({...c,chance:urgent?(c.key===urgent?100:0):total?c.score*c.score/total*100:0})).sort((a,b)=>b.score-a.score);}
function destination(s,p,key){if(key==='sleep')return PLACES.find(x=>x.id===p.home);if(key==='social'){let peers=s.people.filter(x=>x!==p&&sociable.includes(x.action?.key));if(peers.length){peers.sort((a,b)=>relationship(s,p,b).affinity-relationship(s,p,a).affinity);return PLACES.find(x=>x.id===peers[0].action.dest);}return pick(s,PLACES.filter(x=>['park','cafe','disquaire'].includes(x.kind)));}if(key==='form'){const plan=formationPlan(s,p),partner=s.people.find(x=>x.id===plan?.partner);return PLACES.find(x=>x.id===(partner?.action?.dest||partner?.place))||PLACES[0];}if(musical.includes(key))return pick(s,PLACES.filter(x=>x.kind==='garage'));return PLACES.find(x=>x.kind==='park');}
export function locationReason(s,p){const a=p.action;if(!a)return '';if(a.key==='jam'){const j=s.jams.find(x=>x.id===a.sessionId);return `Rendez-vous commun pour la jam${j?' proposée par '+(s.people.find(x=>x.id===j.host)?.name||'un voisin'):''}.`;}if(a.key==='form')return 'Retrouver le partenaire envisagé pour discuter du groupe.';if(musical.includes(a.key))return 'Le garage possède les instruments et l’espace pour faire de la musique.';if(a.key==='sleep')return 'La maison permet de récupérer son énergie.';if(a.key==='relax')return 'Le parc permet de décrocher et de retrouver du confort.';return 'Un lieu de rencontre, choisi pour retrouver un voisin ou changer d’air.';}
function routeTo(s,p,a,dest){a.dest=dest.id;const slot=s.people.indexOf(p),target={x:dest.door.x+(slot%6-2.5)*28,y:dest.door.y+(Math.floor(slot/6)-.5)*34};const same=p.place===dest.id&&Math.hypot(p.x-target.x,p.y-target.y)<100;a.route=same?[]:[{x:p.x,y:340},{x:target.x,y:340},target];if(same){p.x=target.x;p.y=target.y;}}
export function decide(s,p,forced=null,options={}){if(p.action?.remaining>0){if(p.action.elapsed>0)p.actionCounts[p.action.key].interrupted++;closeActivity(s,p,p.action.elapsed>0?'interrupted':'cancelled');}p.candidates=scores(s,p);const urgent=critical(p);let chosen;if(forced&&ACTIONS[forced])chosen=p.candidates.find(c=>c.key===forced);else if(urgent)chosen=p.candidates.find(c=>c.key===urgent);else if(s.decisionMode==='bag'){let roll=rand(s)*100;chosen=p.candidates.find(c=>{roll-=c.chance;return roll<0;})||p.candidates.find(c=>!c.blocked);}else chosen=p.candidates.filter(c=>!c.blocked).map(c=>({...c,weighted:c.score+range(s,-15,15)*s.params.randomness})).sort((a,b)=>b.weighted-a.weighted)[0];
if(chosen.key==='form'&&!formationPlan(s,p)){log(s,'group',`${p.name} ne trouve pas encore de nouveau partenaire admissible.`,[p.id]);chosen=p.candidates.find(c=>c.key==='social');}const key=chosen.key;let dest=destination(s,p,key);const emotion=dominantEmotion(p);p.actionCounts[key].started++;p.action={key,dest:dest.id,remaining:ACTIONS[key].duration,elapsed:0,started:s.time,why:forced?'Intervention manuelle':`${chosen.why}${chosen.emotion?` · émotion ${chosen.emotion>0?'+':''}${chosen.emotion}`:''}${chosen.priority!==2?` · priorité ${PRIORITIES[chosen.priority].toLowerCase()}`:''}${chosen.invite?' · invitation à répéter':''}`,route:[],quality:0,partners:[],solo:false,decision:JSON.parse(JSON.stringify(p.candidates)),mode:forced?'manual':s.decisionMode,waited:0,sessionId:null,formation:key==='form'?formationPlan(s,p):null};if(key==='jam'){const j=assignJam(s,p,options.sessionId);p.action.sessionId=j.id;dest=PLACES.find(x=>x.id===j.place);}routeTo(s,p,p.action,dest);beginActivity(s,p,p.action);if(key==='write')ensureProject(s,p);if(key==='jam'&&!options.sessionId)inviteJamPartner(s,p);
const sources=emotion.active?(p.emotionSources[emotion.key]||[]).slice(0,1):[];log(s,'decision',`${p.name} choisit : ${ACTIONS[key].label.toLowerCase()}. ${p.action.why}.`,[p.id],{causes:sources});return p.action;}
export function conflictRisk(s,a,b){const ra=relationship(s,a,b);return clamp(((100-mood(a))/310+(100-mood(b))/360+(a.traits.includes('hot')?.13:0)+(b.traits.includes('hot')?.09:0)+a.emotions.anger/220+b.emotions.anger/250+a.emotions.fear/800+ra.tension/450-(a.personality.kind+b.personality.kind)/1300)*s.params.conflict,0,.85);}
export function support(s,helper,target){let rh=relationship(s,helper,target),rt=relationship(s,target,helper);const strength=9+helper.personality.kind*.17;const before=target.emotions.anger+target.emotions.sadness+target.emotions.fear;const cause=dominantEmotion(target);const event=log(s,'support',`${helper.name} écoute ${target.name}. L’empathie apaise ${cause.label.toLowerCase()} et renforce leur confiance.`,[helper.id,target.id],{causes:(target.emotionSources[cause.key]||[]).slice(0,1)});feel(s,target,{sadness:-strength,anger:-strength,fear:-strength,affection:9,joy:4},event);feel(s,helper,{affection:6,joy:3},event);for(const r of [rh,rt]){r.trust=clamp(r.trust+5*s.params.relations);r.affinity=clamp(r.affinity+4*s.params.relations,-100,100);r.tension=clamp(r.tension-4*s.params.relations);r.meetings++;r.last=s.time;}memory(s,target,`Écouté par ${helper.name}`,3);return before-(target.emotions.anger+target.emotions.sadness+target.emotions.fear);}
export function advance(s,a,b){const ra=relationship(s,a,b),rb=relationship(s,b,a);if(a.age<18||b.age<18)return null;if(s.time-ra.lastAdvance<720)return null;ra.lastAdvance=s.time;const accepted=rb.attraction>=45&&rb.affinity>=15&&rb.tension<45&&b.emotions.anger<70;const source=log(s,'romance',accepted?`${b.name} accueille les avances de ${a.name} : l’attirance est réciproque.`:`${b.name} décline les avances de ${a.name}.`,[a.id,b.id],{outcome:accepted?'accepted':'rejected'});if(accepted){for(const [p,r] of [[a,ra],[b,rb]]){r.love=clamp(r.love+12*s.params.relations);r.affinity=clamp(r.affinity+5*s.params.relations,-100,100);feel(s,p,{affection:24,joy:14},source);memory(s,p,'Une avance réciproque',4);}}else{ra.love=clamp(ra.love-5*s.params.relations);feel(s,a,{sadness:30,anger:4+(100-a.personality.stable)*.18,fear:6},source);memory(s,a,`Avances déclinées par ${b.name}`,-4);if(a.traits.includes('hot'))ra.tension=clamp(ra.tension+5*s.params.relations);}
return {accepted,event:source};}
export function interact(s,a,b,music=false){const ra=relationship(s,a,b),rb=relationship(s,b,a),chem=chemistry(a,b);let helper=a.personality.kind>=b.personality.kind?a:b,target=helper===a?b:a;let distress=Math.max(target.emotions.sadness,target.emotions.anger,target.emotions.fear);if(helper.personality.kind>=65&&distress>=30&&rand(s)<helper.personality.kind/115){support(s,helper,target);return 'support';}
const conflict=rand(s)<conflictRisk(s,a,b);const causeP=a.emotions.anger>b.emotions.anger?a:b,causeKey=dominantEmotion(causeP).key;const event=log(s,conflict?'conflict':music?'music':'social',conflict?`${a.name} et ${b.name} s’accrochent${music?' pendant la jam':''}.`:`${a.name} et ${b.name} ${music?'trouvent un groove':'se rapprochent'}.`,[a.id,b.id],{causes:conflict?(causeP.emotionSources[causeKey]||[]).slice(0,1):[]});
for(const [p,q,r] of [[a,b,ra],[b,a,rb]]){let empathy=p.personality.kind/100,delta=conflict?-(3+(1-empathy)*4):2+empathy*3+(chem-50)/22;r.affinity=clamp(r.affinity+delta*s.params.relations,-100,100);r.trust=clamp(r.trust+(conflict?-3:1.5)*s.params.relations);r.tension=clamp(r.tension+(conflict?6:-2)*s.params.relations);if(music)r.collaboration=clamp(r.collaboration+(conflict?-1:2+chem/40)*s.params.relations);r.meetings++;r.last=s.time;p.needs.social=clamp(p.needs.social+6);memory(s,p,conflict?`Accrochage avec ${q.name}`:`${music?'Belle jam':'Bon moment'} avec ${q.name}`,conflict?-3:2);feel(s,p,conflict?{anger:11,sadness:4,fear:2}:{joy:5,affection:3,...(music?{excitement:8}:{})},event);}
if(music){for(const p of [a,b])if(p.action){p.action.partners=[...new Set([...p.action.partners,p===a?b.id:a.id])];p.action.quality+=conflict?-5:chem/15;}}
if(!conflict&&!music&&ra.attraction>=55&&ra.affinity>=20&&s.params.romance>0&&rand(s)<.08*s.params.romance)advance(s,a,b);return conflict?'conflict':'positive';}
export const MUSIC_OUTCOMES={sync:'Se synchroniser',learn:'Apprendre un passage',idea:'Trouver une idée',debate:'Débattre d’une direction',clash:'Se marcher dessus',consolidate:'Consolider ses acquis'};
export function musicalOutcome(s,a,b,j){const chem=chemistry(a,b),skillA=a.skills[a.instrument],skillB=b.skills[b.instrument],empathy=(a.personality.kind+b.personality.kind)/2,discipline=(a.personality.discipline+b.personality.discipline)/2,gap=Math.abs(skillA-skillB),trust=Math.min(relationship(s,a,b).trust,relationship(s,b,a).trust),familiarity=Math.min(relationship(s,a,b).collaboration,relationship(s,b,a).collaboration);const weights={sync:10+chem*.2+familiarity*.1,learn:4+gap*empathy/180,idea:4+(a.personality.creative+b.personality.creative)/7+Math.max(a.emotions.excitement,b.emotions.excitement)/10,debate:(a.genre!==b.genre?18:3)+trust/8,clash:conflictRisk(s,a,b)*120,consolidate:10+discipline*.3};let roll=rand(s)*Object.values(weights).reduce((x,y)=>x+y,0);const outcome=Object.keys(weights).find(k=>{roll-=weights[k];return roll<0;})||'consolidate';const count=j.outcomes[outcome]||0,factor=Math.pow(.6,count);j.outcomes[outcome]=count+1;const novice=skillA<=skillB?a:b,mentor=novice===a?b:a;const text={sync:`${a.name} et ${b.name} calent leurs rythmes et se synchronisent.`,learn:`${mentor.name} aide ${novice.name} à maîtriser un passage.`,idea:`${a.name} et ${b.name} trouvent une idée à reprendre en composition.`,debate:`${a.name} et ${b.name} explorent deux directions musicales différentes.`,clash:`${a.name} et ${b.name} se marchent dessus : fatigue ou tension perturbent l’écoute.`,consolidate:`${a.name} et ${b.name} consolident leurs acquis dans une séance régulière.`}[outcome];const explanations={sync:`Compatibilité ${round(chem)}, complicité vécue ${round(familiarity)}.`,learn:`Écart de maîtrise ${round(gap)}, empathie ${round(empathy)}.`,idea:`Créativité ${round((a.personality.creative+b.personality.creative)/2)} et enthousiasme du moment.`,debate:`${a.genre===b.genre?'Styles proches':'Styles différents'}, confiance mutuelle ${round(trust)}.`,clash:`Risque d’accrochage ${round(conflictRisk(s,a,b)*100)} % : humeur, fatigue, émotions, tension et empathie.`,consolidate:`Discipline moyenne ${round(discipline)} ; progrès réguliers.`};const effects={sync:'Complicité et confiance renforcées.',learn:`Maîtrise instrumentale de ${novice.name} améliorée ; confiance renforcée.`,idea:'Une inspiration conservée pour le prochain projet de chacun.',debate:'Expression créative et confiance ; légère tension sans hostilité automatique.',clash:'Complicité et confiance diminuent ; frustration et tension.',consolidate:'Petit progrès instrumental, complicité renforcée.'};const event=log(s,outcome==='clash'?'conflict':'music',text,[a.id,b.id],{activityId:j.id,outcome,explanation:explanations[outcome],effects:effects[outcome],repeatFactor:factor});for(const [p,q] of [[a,b],[b,a]]){const r=relationship(s,p,q),scale=s.params.relations*factor;const delta={sync:[4,3,-2,5],learn:[3.5,2,-1,3],idea:[3.5,2,-1,3],debate:[2,1,1,2],clash:[-3,-3,6,-1],consolidate:[2.5,1.5,-.5,3.5]}[outcome];r.affinity=clamp(r.affinity+delta[0]*scale*(.7+p.personality.kind/150),-100,100);r.trust=clamp(r.trust+delta[1]*scale);r.tension=clamp(r.tension+delta[2]*scale);r.collaboration=clamp(r.collaboration+delta[3]*scale);r.meetings++;r.last=s.time;if(outcome==='consolidate')p.skills[p.instrument]=clamp(p.skills[p.instrument]+.6*factor*s.params.learning);if(outcome==='debate')p.needs.expression=clamp(p.needs.expression+4*factor);if(outcome==='clash')feel(s,p,{anger:5*factor,sadness:2*factor},event);else feel(s,p,{excitement:(outcome==='idea'?7:2)*factor,joy:2*factor},event);if(count===0)memory(s,p,MUSIC_OUTCOMES[outcome]+` avec ${q.name}`,outcome==='clash'?-2:1.5);}
if(outcome==='learn')novice.skills[novice.instrument]=clamp(novice.skills[novice.instrument]+(1+gap/40)*factor*s.params.learning);if(outcome==='clash'&&empathy>=70){const helper=a.personality.kind>=b.personality.kind?a:b;support(s,helper,helper===a?b:a);}return event;}

function sampleDraft(s,p){const d=p.draft;if(d.samples>=75)return;d.samples++;for(const k of Object.keys(EMOTIONS))d.emotions[k]+=p.emotions[k];d.authors=[...new Set([...d.authors,p.id,...p.action.partners])];const e=dominantEmotion(p);if(e.active)for(const source of p.emotionSources[e.key]||[]){if(!d.sources.some(x=>x.id===source.id))d.sources.push({...source,emotion:e.key});}d.sources=d.sources.slice(-8);if(p.action.partners.length){d.jamQuality+=p.action.quality/Math.max(1,p.action.elapsed/15);d.jamSamples++;}}
export function songOutcome(s,p){const d=p.draft,samples=Math.max(1,d.samples),average=Object.fromEntries(Object.entries(d.emotions).map(([k,v])=>[k,v/samples]));const project=compositionProject(s,p);const [sampleEmotion,sampleIntensity]=Object.entries(average).sort((a,b)=>b[1]-a[1])[0];const emotion=project?.emotion||sampleEmotion,intensity=project?.intensity??sampleIntensity;const craft=p.skills.writing*.45+p.skills[p.instrument]*.25;const expression=intensity/100*(6+p.personality.creative*.12);const overwhelm=Math.max(0,intensity-72)*(100-p.personality.stable)/190;const ensemble=d.jamSamples?clamp(d.jamQuality/d.jamSamples,0,12):0;const perfection=p.traits.includes('perfectionist')?8:0;const variance=range(s,3,13);const quality=clamp(craft+expression+ensemble+perfection+variance-overwhelm);const fit=0;const resonance=clamp(quality*.65+intensity*.2+fit+range(s,0,18));return {emotion,intensity:round(intensity),tone:intensity<10?'posée':EMOTIONS[emotion].tone,quality:round(quality),resonance:round(resonance),breakdown:{craft:round(craft),expression:round(expression),ensemble:round(ensemble),perfection,overwhelm:round(overwhelm),variance:round(variance)}};}
function releaseSong(s,p){const project=ensureProject(s,p),result=songOutcome(s,p);const song={id:s.nextSongId++,projectId:project.id,title:project.title,time:s.time,...result,genre:project.genre,authors:[p.id],sources:[...p.draft.sources],hit:result.resonance>=80};s.songs.unshift(song);project.status='finished';project.songId=song.id;project.updated=s.time;project.quality=song.quality;const ev=log(s,'song',`« ${song.title} » : une chanson ${result.tone} de ${p.name}. Qualité ${result.quality}/100.`,song.authors,{causes:song.sources.slice(-3)});feel(s,p,{joy:song.hit?16:6,excitement:5},ev);memory(s,p,'Une chanson terminée',5);p.draft=defaultDraft();p.songProgress=0;refreshReputation(s,p);return song;}

function finish(s,p){const a=p.action;p.actionCounts[a.key].completed++;if(a.key==='write'){const project=ensureProject(s,p);project.sessions++;log(s,'project',`${p.name} avance « ${project.title} » : ${round(p.songProgress)} %, ${project.sessions} séance${project.sessions>1?'s':''}.`,[p.id],{projectId:project.id});if(project.work>=project.target)releaseSong(s,p);}if(a.key==='form'){p.lastFormation=s.time;const plan=a.formation,q=s.people.find(x=>x.id===plan?.partner);if(q&&formationEligible(s,p,q)&&p.place===q.place&&!q.action?.route.length){const g=s.groups.find(x=>x.id===plan.groupId);if(g&&!g.members.includes(p.id)){g.members.push(p.id);log(s,'group',`${p.name} rejoint « ${g.name} » après ses échanges avec ${q.name}.`,[p.id,q.id],{groupId:g.id});}else if(!g)createGroup(s,[p.id,q.id]);}else log(s,'group',`${p.name} reporte la formation : le partenaire est parti ou les liens ne sont plus suffisants.`,[p.id]);}a.remaining=0;closeActivity(s,p);decide(s,p);}
function assignJam(s,p,sessionId){let session=sessionId?s.jams.find(j=>j.id===sessionId):s.jams.filter(j=>j.status!=='finished'&&j.elapsed<60&&s.time-j.created<180).sort((a,b)=>{const rank=j=>j.participants.reduce((v,id)=>{const q=s.people.find(x=>x.id===id);return v+(q&&q!==p?relationship(s,p,q).affinity*.3+q.reputation.score*.15:0);},0);return rank(b)-rank(a);})[0];if(!session){const dest=PLACES.find(x=>x.id===p.action.dest);session={id:`j${s.nextJamId++}`,place:dest.kind==='garage'?dest.id:'g1',host:p.id,participants:[],created:s.time,elapsed:0,status:'waiting',playedPairs:[],outcomes:{}};s.jams.push(session);beginActivity(s,p,{...p.action,sessionId:session.id});log(s,'jam',`${p.name} propose une jam au ${PLACES.find(x=>x.id===session.place).name}.`,[p.id],{activityId:session.id});}if(!session.participants.includes(p.id))session.participants.push(p.id);return session;}
function inviteJamPartner(s,p){const j=s.jams.find(x=>x.id===p.action.sessionId);if(j.participants.length>=2)return;const candidates=s.people.filter(q=>q!==p&&q.priorities.jam>0&&q.needs.energy>=25&&q.emotions.anger<80&&(!q.action||['practice','social','relax'].includes(q.action.key))).sort((a,b)=>chemistry(p,b)+relationship(s,p,b).affinity*.4+b.reputation.score*.2-chemistry(p,a)-relationship(s,p,a).affinity*.4-a.reputation.score*.2);if(candidates[0]){const q=candidates[0];decide(s,q,'jam',{sessionId:j.id});q.action.why=`Invitation de ${p.name} acceptée`;log(s,'jam',`${q.name} accepte la jam de ${p.name} et se met en route.`,[p.id,q.id]);}}
export function liveSessions(s){const result=[];for(const j of s.jams.filter(j=>j.status==='active')){const ids=j.participants.filter(id=>{const p=s.people.find(x=>x.id===id);return p?.action?.sessionId===j.id&&!p.action.route.length;});if(ids.length>=2){const shared=s.groups.find(g=>ids.every(id=>g.members.includes(id)));result.push({id:j.id,type:'jam',label:shared?`Jam · ${shared.name}`:'Jam ensemble',place:j.place,participants:ids});}}for(const place of PLACES){const people=s.people.filter(p=>p.action?.key==='social'&&!p.action.route.length&&p.place===place.id);if(people.length>=2)result.push({id:'social-'+place.id,type:'social',label:'Socialisent ensemble',place:place.id,participants:people.map(x=>x.id)});}return result;}
function updateJams(s){for(const j of [...s.jams]){if(j.status==='finished')continue;const participants=s.people.filter(p=>p.action?.key==='jam'&&p.action.sessionId===j.id),present=participants.filter(p=>!p.action.route.length);j.participants=participants.map(x=>x.id);const row=s.activities.find(x=>x.id===j.id);if(!participants.length){j.status='finished';if(row){row.status='cancelled';row.end=s.time;}continue;}if(present.length<2){j.status='waiting';if(row)row.status='waiting';for(const p of present){p.action.waited++;if(p.action.waited>=90){log(s,'jam',`${p.name} n’a plus de partenaire : la jam est annulée, place à la pratique solo.`,[p.id]);decide(s,p,'practice');}}continue;}if(j.status!=='active')log(s,'jam',`${present.map(x=>x.name).join(' et ')} commencent à jammer ensemble.`,present.map(x=>x.id));j.status='active';j.elapsed++;if(row){row.status='active';row.activeMinutes=j.elapsed;}for(let i=0;i<present.length;i++)for(let k=i+1;k<present.length;k++){const key=[present[i].id,present[k].id].sort().join('/');if(!j.playedPairs.includes(key))j.playedPairs.push(key);}for(const p of present){const a=p.action;a.elapsed++;a.remaining=Math.max(0,85-j.elapsed);a.partners=present.filter(q=>q!==p).map(q=>q.id);p.needs.expression=clamp(p.needs.expression+.7);p.needs.fun=clamp(p.needs.fun+.5);p.needs.social=clamp(p.needs.social+.6);p.needs.energy=clamp(p.needs.energy-.05);p.skills[p.instrument]=clamp(p.skills[p.instrument]+.013*s.params.learning);}if(j.elapsed%15===0){const a=pick(s,present),b=pick(s,present.filter(x=>x!==a));musicalOutcome(s,a,b,j);}if(j.elapsed>=85){j.status='finished';if(row){row.status='completed';row.end=s.time;}for(const key of j.playedPairs){const [aid,bid]=key.split('/'),a=s.people.find(x=>x.id===aid),b=s.people.find(x=>x.id===bid);if(a&&b){relationship(s,a,b).musicSessions++;relationship(s,b,a).musicSessions++;}}log(s,'jam',`La jam se termine : ${present.map(x=>x.name).join(', ')}.`,present.map(x=>x.id));for(const p of participants){p.action.remaining=0;if(p.action.elapsed>0)p.actionCounts.jam.completed++;refreshReputation(s,p);decide(s,p);}}}s.jams=s.jams.filter(j=>j.status!=='finished'||s.time-j.created<300);}
export function step(s,minutes=1){for(let tick=0;tick<minutes;tick++){s.time++;for(const p of s.people){p.memories=p.memories.filter(m=>m.until>s.time);for(const k of Object.keys(EMOTIONS))p.emotions[k]=clamp(p.emotions[k]-(.025+p.personality.stable*.00065)*s.params.emotionDecay);for(const [k,d] of Object.entries({energy:.065,social:.035,fun:.04,expression:.05,comfort:.03}))p.needs[k]=clamp(p.needs[k]-d*s.params.drain*(k==='social'?(p.traits.includes('loner')?.5:1+p.personality.outgoing/200):1));if(!p.action)decide(s,p);let a=p.action;if((p.needs.energy<8&&a.key!=='sleep')&&(a.elapsed>15||a.waited>15)){log(s,'system',`${p.name} interrompt son activité : besoin urgent.`,[p.id]);decide(s,p);a=p.action;}
if(a.route.length){const t=a.route[0],dist=Math.hypot(t.x-p.x,t.y-p.y),speed=12;if(dist<=speed){p.x=t.x;p.y=t.y;a.route.shift();if(!a.route.length)p.place=a.dest;}else{p.x+=(t.x-p.x)*speed/dist;p.y+=(t.y-p.y)*speed/dist;}continue;}
if(a.key==='jam')continue;const row=s.activities.find(x=>x.id===a.activityId);if(row){row.status='active';row.activeMinutes=a.elapsed+1;}a.elapsed++;a.remaining--;let peers=s.people.filter(b=>b!==p&&!b.action?.route.length&&b.place===p.place);let partners=peers.filter(b=>musical.includes(b.action?.key));let isJam=a.key==='jam'&&partners.length>0;let effects={sleep:{energy:.7,comfort:.3},social:{social:peers.length?.8:.1,fun:.25},practice:{expression:.6,fun:.26,energy:-.055},jam:{expression:isJam?.7:.3,fun:isJam?.6:.1,social:isJam?.65:0,energy:-.05},write:{expression:.65,fun:.2,energy:-.03},relax:{fun:.8,comfort:.8,energy:.07},form:{social:.3,fun:.1}}[a.key];for(const [k,d] of Object.entries(effects))p.needs[k]=clamp(p.needs[k]+d*(k==='expression'&&p.traits.includes('perfectionist')?.8:1));if(['sleep','relax'].includes(a.key))feel(s,p,{anger:-.07,fear:-.07,sadness:-.03});
if(musical.includes(a.key)){p.skills[p.instrument]=clamp(p.skills[p.instrument]+.009*s.params.learning*(p.traits.includes('virtuoso')?1.4:1));if(a.key==='write')p.skills.writing=clamp(p.skills.writing+.018*s.params.learning);if(a.key==='write'){sampleDraft(s,p);advanceProject(s,p);}}
if(a.elapsed%15===0){let possible=sociable.includes(a.key)?peers.filter(b=>sociable.includes(b.action?.key)):a.key==='jam'?partners:[];if(possible.length)interact(s,p,pick(s,possible),a.key==='jam');else if(a.key==='jam'&&!a.solo){a.solo=true;log(s,'music',`${p.name} attend des partenaires et pratique en solo.`,[p.id]);}}
if(a.remaining<=0)finish(s,p);}
updateJams(s);if(s.time%30===0)for(const p of s.people){p.history.push({time:s.time,mood:round(mood(p)),emotion:dominantEmotion(p).key});p.history=p.history.slice(-96);}if(s.time%60===0){for(const p of s.people)refreshReputation(s,p);for(const r of Object.values(s.rels)){r.tension=clamp(r.tension-.4);if(s.time-r.last>1440){r.affinity*=.999;r.love*=.999;}}s.history.push({time:s.time,mood:round(s.people.reduce((a,p)=>a+mood(p),0)/Math.max(1,s.people.length))});s.history=s.history.slice(-168);}}return s;}
export function removePerson(s,id){if(s.people.length<=1)return;const departing=s.people.find(p=>p.id===id);if(departing){closeActivity(s,departing,'interrupted');const row=s.activities.find(x=>x.id===departing.action?.activityId);if(row&&departing.action?.key==='jam')log(s,'jam',`${departing.name} quitte la session.`,[id],{activityId:row.id});}s.people=s.people.filter(p=>p.id!==id);for(const k of Object.keys(s.rels))if(k.split('>').includes(id))delete s.rels[k];for(const p of s.people)if(p.action)p.action.partners=p.action.partners.filter(x=>x!==id);for(const g of s.groups){g.members=g.members.filter(x=>x!==id);g.founders=g.founders.filter(x=>x!==id);}s.groups=s.groups.filter(g=>g.members.length);for(const j of s.jams)j.participants=j.participants.filter(x=>x!==id);log(s,'system','Un personnage quitte le quartier.',[id]);}
export function scenario(s,name){s.scenario=name;s.params={...DEFAULTS};if(name==='Tensions'){s.params.conflict=2.4;s.params.relations=1.4;const ev=log(s,'system','Expérience : le quartier est à cran.');for(const p of s.people){p.needs.social=30;p.personality.kind=25;p.traits=[...new Set([...p.traits,'hot'])];feel(s,p,{anger:40},ev);decide(s,p,'social');}}else if(name==='Soirée jam'){const day=Math.floor(s.time/1440);s.time=day*1440+1080+(s.time%1440>1080?1440:0);s.params.music=1.6;for(const p of s.people){p.needs.energy=85;p.needs.expression=25;p.needs.social=35;decide(s,p,'jam');}}else if(name==='Cœur brisé'){if(s.people.length<3)while(s.people.length<3)addPerson(s);const [a,b,c]=s.people;for(const p of [a,b,c]){p.emotions=emptyEmotions();p.emotionSources={};p.memories=[];p.needs.energy=90;}a.songProgress=0;a.draft=defaultDraft();a.personality.creative=90;a.personality.stable=25;a.priorities.write=1;a.priorities.jam=3;a.priorities.practice=3;const r=relationship(s,a,b),rb=relationship(s,b,a);r.affinity=40;r.attraction=90;r.lastAdvance=-1440;rb.attraction=5;c.personality.kind=95;const result=advance(s,a,b);feel(s,a,{sadness:28,anger:18},result?.event);decide(s,a,'write');log(s,'system',`Expérience préparée : ${a.name} compose après un rejet. ${c.name} peut l’apaiser si leurs chemins se croisent.`,[a.id,b.id,c.id]);}else if(name==='Équilibre'){for(const p of s.people)decide(s,p);}log(s,'system',`Scénario : ${name}.`);}
// Migration adds new systems without resetting the existing cast, relationships or clock.
function migrate(raw){const upgrade=raw.version!==VERSION;const old=raw.version==='0.1.0',previous=['0.1.0','0.2.0'].includes(raw.version);if(!previous&&!['0.3.0',VERSION].includes(raw.version))return raw;if(old){raw.version=VERSION;raw.params={...DEFAULTS,...raw.params};raw.decisionMode='utility';raw.nextSongId=Math.max(0,...raw.songs.map(x=>x.id))+1;raw.band={name:'Les Voisins du garage',leader:raw.people[0].id,members:raw.people.slice(0,3).map(x=>x.id),genre:'Indie',focus:'balanced',rehearsal:null};for(const p of raw.people){for(const k of ['sax','trumpet','percussion'])p.skills[k]=10;p.emotions={...emptyEmotions(),joy:12,excitement:10};p.emotionSources={};p.priorities=priorities();p.draft=defaultDraft();p.lastRecruit=-1440;if(p.action){p.action.started=raw.time-p.action.elapsed;p.action.mode='utility';p.action.decision=[];}}for(const [key,r] of Object.entries(raw.rels)){const [a,b]=key.split('>').map(id=>raw.people.find(p=>p.id===id));if(a&&b){r.attraction=attraction(a,b);r.love=0;r.lastAdvance=-1440;}}for(const song of raw.songs){song.sources=[];song.emotion='joy';song.tone='non mesurée (V0.1)';song.intensity=0;song.resonance=null;song.breakdown=null;song.hit=false;song.band=null;}}if(previous){raw.version=VERSION;raw.groups=raw.band?[{id:'g1',name:raw.band.name,members:[...raw.band.members],founders:[raw.band.leader],created:raw.time,genre:raw.band.genre,origin:'migration'}]:[];raw.nextGroupId=raw.groups.length+1;raw.nextJamId=1;raw.jams=[];delete raw.band;for(const p of raw.people){delete p.needs.food;delete p.money;delete p.lastRecruit;p.lastFormation=-1440;p.actionCounts=Object.fromEntries(Object.keys(ACTIONS).map(k=>[k,{started:0,completed:0,interrupted:0}]));p.countsSince=raw.time;p.priorities=Object.fromEntries(Object.keys(ACTIONS).map(k=>[k,p.priorities?.[k]??2]));p.action=null;p.candidates=[];p.reputation={score:0,skill:0,catalogue:0,recognition:0,collaboration:0};}log(raw,'system','Migration V0.3 : alimentation et travail retirés. Compteurs d’actions démarrés maintenant ; ancien band conservé comme groupe.');for(const p of raw.people)refreshReputation(raw,p);}if(upgrade){raw.version=VERSION;raw.params={...DEFAULTS,...raw.params};raw.activities=[];raw.projects=[];raw.nextActivityId=1;raw.nextProjectId=1;for(const r of Object.values(raw.rels))r.musicSessions=0;for(const j of raw.jams){j.playedPairs=[];j.outcomes={};}for(const p of raw.people){p.draft.projectId=null;if(p.action){beginActivity(raw,p,p.action);if(p.action.key==='write'){const project=ensureProject(raw,p);project.work=Math.min(project.target-1,p.action.elapsed);project.sessions=0;p.songProgress=project.work/project.target*100;}}}log(raw,'system','V0.4 : projets de chansons et bilans de sessions. La découverte de chimie commence maintenant ; aucune expérience passée inventée.');}return raw;}
export function restore(input){if(!input||!['0.1.0','0.2.0','0.3.0',VERSION].includes(input.version)||!Array.isArray(input.people)||!input.people.length||input.people.length>24||!Array.isArray(input.songs)||!input.params||!input.rels)throw Error('Sauvegarde incompatible ou incomplète.');const raw=migrate(JSON.parse(JSON.stringify(input)));const num=(v,min=0,max=100)=>Number.isFinite(v)&&v>=min&&v<=max;const source=x=>x&&Number.isInteger(x.id)&&Number.isFinite(x.time)&&typeof x.text==='string';if(!Array.isArray(raw.history)||!Number.isInteger(raw.time)||raw.time<0||!Number.isInteger(raw.rng)||!Number.isInteger(raw.nextId)||!Number.isInteger(raw.eventId)||!Number.isInteger(raw.nextSongId)||!Array.isArray(raw.events)||!['utility','bag'].includes(raw.decisionMode))throw Error('Monde invalide.');const ids=new Set();for(const p of raw.people){if(!/^p\d+$/.test(p.id)||ids.has(p.id)||typeof p.name!=='string'||p.name.length>80||typeof p.color!=='string'||!/^#[0-9a-f]{6}$/i.test(p.color)||!num(p.age,16,100)||!Object.hasOwn(SKILLS,p.instrument)||p.instrument==='writing'||!GENRES.includes(p.genre)||!Array.isArray(p.traits)||p.traits.some(t=>!Object.hasOwn(TRAITS,t))||!num(p.x,0,1100)||!num(p.y,0,670)||!Array.isArray(p.memories)||!Array.isArray(p.history)||!num(p.songProgress)||!Number.isFinite(p.lastFormation)||!Number.isFinite(p.countsSince))throw Error('Personnage invalide.');if(p.memories.some(m=>typeof m.text!=='string'||!Number.isFinite(m.effect)||!Number.isFinite(m.until))||p.history.some(h=>!Number.isFinite(h.time)||!num(h.mood)))throw Error('Historique invalide.');ids.add(p.id);for(const [key,shape] of [['needs',NEEDS],['personality',PERSONALITY],['skills',SKILLS],['emotions',EMOTIONS]])for(const k of Object.keys(shape))if(!num(p[key]?.[k]))throw Error('Statistique invalide.');for(const key of Object.keys(ACTIONS))if(!Number.isInteger(p.priorities?.[key])||!num(p.priorities[key],0,3))throw Error('Priorité invalide.');if(!p.emotionSources||Object.values(p.emotionSources).some(xs=>!Array.isArray(xs)||xs.some(x=>!source(x)))||!p.draft||!Array.isArray(p.draft.sources)||p.draft.sources.some(x=>!source(x))||!Array.isArray(p.draft.authors)||!num(p.draft.samples,0,1e9)||!num(p.draft.jamSamples,0,1e9)||!Number.isFinite(p.draft.jamQuality)||Object.keys(EMOTIONS).some(k=>!num(p.draft.emotions[k],0,1e12)))throw Error('Composition ou émotion invalide.');if(!PLACES.some(x=>x.id===p.home)||!PLACES.some(x=>x.id===p.place)||p.action&&(!Object.hasOwn(ACTIONS,p.action.key)||!PLACES.some(x=>x.id===p.action.dest)||!Array.isArray(p.action.route)||p.action.route.some(x=>!num(x.x,0,1100)||!num(x.y,0,670))||!Number.isFinite(p.action.elapsed)||!Number.isFinite(p.action.remaining)||!Number.isFinite(p.action.quality)||!Array.isArray(p.action.partners)||!Array.isArray(p.action.decision)))throw Error('Activité invalide.');}
for(const k of Object.keys(DEFAULTS))if(!num(raw.params[k],0,3))throw Error('Paramètre invalide.');for(const [key,r] of Object.entries(raw.rels)){if(key.split('>').length!==2||key.split('>').some(x=>!ids.has(x)))throw Error('Relation invalide.');for(const k of ['affinity','trust','tension','collaboration','attraction','love','meetings','last','lastAdvance'])if(!Number.isFinite(r[k]))throw Error('Relation invalide.');for(const k of ['trust','tension','collaboration','attraction','love'])if(!num(r[k]))throw Error('Relation hors limites.');if(!num(r.affinity,-100,100))throw Error('Affinité invalide.');}if(raw.events.some(e=>typeof e.text!=='string'||!Array.isArray(e.ids)||!Number.isFinite(e.time)||e.causes&&(!Array.isArray(e.causes)||e.causes.some(x=>!source(x))))||raw.songs.some(s=>typeof s.title!=='string'||!Array.isArray(s.authors)||!Number.isFinite(s.time)||!num(s.quality)||!Array.isArray(s.sources)||s.sources.some(x=>!source(x))||!EMOTIONS[s.emotion]))throw Error('Journal invalide.');if(!Array.isArray(raw.groups)||!Array.isArray(raw.jams)||!Number.isInteger(raw.nextGroupId)||!Number.isInteger(raw.nextJamId))throw Error('Groupes ou sessions invalides.');const groupIds=new Set();for(const g of raw.groups){if(typeof g.id!=='string'||groupIds.has(g.id)||typeof g.name!=='string'||!Array.isArray(g.members)||!g.members.length||new Set(g.members).size!==g.members.length||g.members.some(x=>!ids.has(x))||!Array.isArray(g.founders)||!GENRES.includes(g.genre)||!Number.isFinite(g.created))throw Error('Groupe invalide.');groupIds.add(g.id);}for(const j of raw.jams)if(typeof j.id!=='string'||!PLACES.some(p=>p.id===j.place)||!Array.isArray(j.participants)||j.participants.some(id=>!ids.has(id))||!num(j.elapsed,0,85)||!Number.isFinite(j.created)||!['waiting','active','finished'].includes(j.status))throw Error('Jam invalide.');for(const p of raw.people){for(const k of Object.keys(ACTIONS))for(const f of ['started','completed','interrupted'])if(!Number.isInteger(p.actionCounts?.[k]?.[f])||p.actionCounts[k][f]<0)throw Error('Compteur invalide.');if(!num(p.reputation?.score))throw Error('Réputation invalide.');if(p.action?.key==='jam'&&!raw.jams.some(j=>j.id===p.action.sessionId))throw Error('Session manquante.');} if(!Array.isArray(raw.activities)||!Array.isArray(raw.projects)||!Number.isInteger(raw.nextActivityId)||raw.nextActivityId<1||!Number.isInteger(raw.nextProjectId)||raw.nextProjectId<1)throw Error('Projets ou activités invalides.');const projectIds=new Set();const activityIds=new Set();for(const project of raw.projects){if(!/^c\d+$/.test(project.id)||typeof project.author!=='string'||projectIds.has(project.id)||typeof project.title!=='string'||!Number.isFinite(project.target)||project.target<=0||!num(project.work,0,project.target)||!Number.isInteger(project.sessions)||project.sessions<0||!['idea','draft','ready','finished'].includes(project.status)||!EMOTIONS[project.emotion]||!GENRES.includes(project.genre)||!Array.isArray(project.sources)||project.sources.some(x=>!source(x))||!num(project.potential)||!num(project.intensity)||!Number.isFinite(project.created)||!Number.isFinite(project.updated))throw Error('Projet invalide.');projectIds.add(project.id);}for(const p of raw.people)if(p.draft.projectId&&(!projectIds.has(p.draft.projectId)||raw.projects.find(x=>x.id===p.draft.projectId).author!==p.id))throw Error('Projet manquant.');if(raw.nextProjectId<=Math.max(0,...raw.projects.map(x=>Number(x.id.slice(1)))))throw Error('Identifiant de projet invalide.');for(const a of raw.activities){if(typeof a.id!=='string'||activityIds.has(a.id)||!ACTIONS[a.key]||!Array.isArray(a.ids)||!Array.isArray(a.events)||a.events.some(e=>!source(e)||!Array.isArray(e.ids))||!Number.isFinite(a.time)||!Number.isFinite(a.activeMinutes)||!['travel','active','waiting','completed','interrupted','cancelled'].includes(a.status))throw Error('Bilan invalide.');activityIds.add(a.id);}for(const p of raw.people)if(p.action&&!activityIds.has(p.action.activityId))throw Error('Bilan manquant.');for(const r of Object.values(raw.rels))if(!Number.isInteger(r.musicSessions)||r.musicSessions<0)throw Error('Découverte invalide.');for(const j of raw.jams)if(!Array.isArray(j.playedPairs)||j.playedPairs.some(x=>typeof x!=='string')||!j.outcomes||typeof j.outcomes!=='object'||Object.values(j.outcomes).some(v=>!Number.isInteger(v)||v<0))throw Error('Expérience musicale invalide.');if(raw.nextId<=Math.max(...raw.people.map(p=>Number(p.id.slice(1)))))throw Error('Identifiant de personnage invalide.');return raw;}
